CREATE TABLE owners(id TEXT PRIMARY KEY, timezone TEXT NOT NULL, created_at REAL NOT NULL);
CREATE TABLE control(owner_id TEXT NOT NULL REFERENCES owners(id), key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(owner_id,key));
CREATE TABLE conversations(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), channel TEXT NOT NULL, target TEXT NOT NULL, sequence INTEGER NOT NULL DEFAULT 0, backend TEXT, model TEXT, last_engagement REAL, UNIQUE(owner_id,channel,target));
CREATE TABLE inbox_updates(owner_id TEXT NOT NULL REFERENCES owners(id), channel TEXT NOT NULL, update_id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), received_at REAL NOT NULL, PRIMARY KEY(owner_id,channel,update_id));
CREATE TABLE messages(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), sequence INTEGER NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','assistant','tool','checkpoint')), content TEXT NOT NULL, parts TEXT NOT NULL DEFAULT '[]', source TEXT, run_id TEXT, created_at REAL NOT NULL, UNIQUE(conversation_id,sequence));
CREATE INDEX messages_recent ON messages(owner_id,conversation_id,sequence DESC);
CREATE TABLE memory_records(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), kind TEXT NOT NULL, revision INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','archived')), importance REAL NOT NULL CHECK(importance BETWEEN 0 AND 1), pinned INTEGER NOT NULL DEFAULT 0, created_at REAL NOT NULL, updated_at REAL NOT NULL);
CREATE TABLE memory_revisions(memory_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, version INTEGER NOT NULL, body TEXT NOT NULL, provenance TEXT NOT NULL CHECK(provenance IN ('owner','verified','inference','import')), source TEXT NOT NULL, metadata TEXT NOT NULL CHECK(json_valid(metadata)), created_at REAL NOT NULL, PRIMARY KEY(memory_id,version));
CREATE TABLE memory_edges(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), source_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, target_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, relation TEXT NOT NULL, provenance TEXT NOT NULL, valid_from REAL NOT NULL, valid_to REAL, CHECK(source_id<>target_id), UNIQUE(source_id,target_id,relation));
CREATE TABLE corrections(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), memory_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, expected_revision INTEGER NOT NULL, body TEXT NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','accepted','rejected')), created_at REAL NOT NULL, decided_at REAL);
CREATE VIRTUAL TABLE memory_fts USING fts5(memory_id UNINDEXED,owner_id UNINDEXED,body,tokenize='unicode61');
CREATE TABLE embeddings(memory_id TEXT NOT NULL REFERENCES memory_records(id) ON DELETE CASCADE, revision INTEGER NOT NULL, model TEXT NOT NULL, dimensions INTEGER NOT NULL, preprocessing TEXT NOT NULL, vector BLOB NOT NULL, PRIMARY KEY(memory_id,model));
CREATE TABLE embedding_jobs(memory_id TEXT PRIMARY KEY REFERENCES memory_records(id) ON DELETE CASCADE, revision INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, retry_at REAL NOT NULL DEFAULT 0);
CREATE TABLE facts(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), subject TEXT NOT NULL, predicate TEXT NOT NULL, revision INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'active', UNIQUE(owner_id,subject,predicate));
CREATE TABLE fact_revisions(fact_id TEXT NOT NULL REFERENCES facts(id) ON DELETE CASCADE, version INTEGER NOT NULL, value TEXT NOT NULL, source TEXT NOT NULL, provenance TEXT NOT NULL, recorded_at REAL NOT NULL, valid_from REAL NOT NULL, valid_to REAL, PRIMARY KEY(fact_id,version));
CREATE TABLE persona_versions(owner_id TEXT NOT NULL REFERENCES owners(id), version INTEGER NOT NULL, body TEXT NOT NULL, created_at REAL NOT NULL, PRIMARY KEY(owner_id,version));
CREATE TABLE attention_pins(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), body TEXT NOT NULL, source TEXT NOT NULL, expires_at REAL, created_at REAL NOT NULL);
CREATE TABLE skills(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), name TEXT NOT NULL, version INTEGER NOT NULL, body TEXT NOT NULL, triggers TEXT NOT NULL, grants TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL CHECK(status IN ('proposed','tested','active','retired')), evaluation TEXT, source TEXT NOT NULL, created_at REAL NOT NULL, UNIQUE(owner_id,name,version));
CREATE TABLE feedback(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), run_id TEXT, action_id TEXT, kind TEXT NOT NULL, body TEXT NOT NULL, explicit INTEGER NOT NULL, created_at REAL NOT NULL);
CREATE TABLE goals(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), conversation_id TEXT REFERENCES conversations(id), title TEXT NOT NULL, criteria TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','active','blocked','paused','completed','abandoned')), blocker TEXT, evidence TEXT, created_at REAL NOT NULL, updated_at REAL NOT NULL, CHECK(status<>'completed' OR length(evidence)>0));
CREATE TABLE plan_steps(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), goal_id TEXT NOT NULL REFERENCES goals(id), ordinal INTEGER NOT NULL, title TEXT NOT NULL, next_action TEXT NOT NULL, capabilities TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL CHECK(status IN ('pending','active','blocked','completed')), evidence TEXT, CHECK(status<>'completed' OR length(evidence)>0), UNIQUE(goal_id,ordinal));
CREATE TABLE step_dependencies(step_id TEXT NOT NULL REFERENCES plan_steps(id), depends_on TEXT NOT NULL REFERENCES plan_steps(id), PRIMARY KEY(step_id,depends_on), CHECK(step_id<>depends_on));
CREATE TABLE commitments(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), goal_id TEXT REFERENCES goals(id), body TEXT NOT NULL, due_at REAL, status TEXT NOT NULL, evidence TEXT);
CREATE TABLE schedules(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), body TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('once','cron','interval')), cron TEXT, interval_seconds INTEGER, timezone TEXT NOT NULL, next_due REAL NOT NULL, active INTEGER NOT NULL DEFAULT 1, grace_seconds INTEGER NOT NULL DEFAULT 3600, created_at REAL NOT NULL);
CREATE TABLE occurrences(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), schedule_id TEXT NOT NULL REFERENCES schedules(id), nominal_due REAL NOT NULL, job_id TEXT NOT NULL, UNIQUE(schedule_id,nominal_due));
CREATE TABLE jobs(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), parent_id TEXT REFERENCES jobs(id), root_id TEXT NOT NULL, kind TEXT NOT NULL, lane TEXT NOT NULL CHECK(lane IN ('interactive','background')), status TEXT NOT NULL CHECK(status IN ('queued','running','waiting_for_auth','waiting_for_quota','waiting_for_user','waiting_for_dependency','completed','failed','interrupted','cancelled','uncertain')), payload TEXT NOT NULL CHECK(json_valid(payload)), semantic_key TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 0, lease_until REAL, worker TEXT, attempts INTEGER NOT NULL DEFAULT 0, deadline REAL NOT NULL, available_at REAL NOT NULL, outcome TEXT, created_at REAL NOT NULL, updated_at REAL NOT NULL, UNIQUE(owner_id,semantic_key));
CREATE INDEX jobs_ready ON jobs(owner_id,lane,status,available_at);
CREATE UNIQUE INDEX one_active_conversation ON jobs(conversation_id) WHERE status='running';
CREATE TABLE job_dependencies(job_id TEXT NOT NULL REFERENCES jobs(id), depends_on TEXT NOT NULL REFERENCES jobs(id), PRIMARY KEY(job_id,depends_on), CHECK(job_id<>depends_on));
CREATE TABLE runs(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), job_id TEXT NOT NULL REFERENCES jobs(id), generation INTEGER NOT NULL, backend TEXT NOT NULL, model TEXT NOT NULL, context_id TEXT, status TEXT NOT NULL, output TEXT, error TEXT, input_tokens INTEGER, output_tokens INTEGER, started_at REAL NOT NULL, ended_at REAL, UNIQUE(job_id,generation));
CREATE TABLE run_events(event_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), run_id TEXT NOT NULL REFERENCES runs(id), sequence INTEGER NOT NULL, kind TEXT NOT NULL, payload TEXT NOT NULL, created_at REAL NOT NULL, UNIQUE(run_id,sequence));
CREATE UNIQUE INDEX one_terminal_event ON run_events(run_id) WHERE kind='terminal';
CREATE TABLE context_snapshots(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), sequence INTEGER NOT NULL, rendered TEXT NOT NULL, sources TEXT NOT NULL, candidates TEXT NOT NULL, estimated_tokens INTEGER NOT NULL, degraded INTEGER NOT NULL, created_at REAL NOT NULL, invalidated INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), backend TEXT NOT NULL, account TEXT NOT NULL, workspace TEXT NOT NULL, native_id TEXT NOT NULL, canonical_sequence INTEGER NOT NULL, fingerprint TEXT NOT NULL, valid INTEGER NOT NULL DEFAULT 1);
CREATE TABLE actions(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), conversation_id TEXT NOT NULL REFERENCES conversations(id), job_id TEXT REFERENCES jobs(id), run_id TEXT, generation INTEGER, semantic_key TEXT NOT NULL, operation TEXT NOT NULL, request TEXT NOT NULL CHECK(json_valid(request)), request_hash TEXT NOT NULL, target TEXT NOT NULL, scope TEXT NOT NULL, policy_version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('prepared','awaiting_approval','ready','executing','succeeded','failed','uncertain','cancelled')), expires_at REAL NOT NULL, source_sequence INTEGER NOT NULL, freshness TEXT NOT NULL DEFAULT '{}', receipt TEXT, error TEXT, created_at REAL NOT NULL, updated_at REAL NOT NULL, UNIQUE(owner_id,semantic_key));
CREATE TABLE approvals(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), action_id TEXT NOT NULL REFERENCES actions(id), request_hash TEXT NOT NULL, target TEXT NOT NULL, scope TEXT NOT NULL, expires_at REAL NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('pending','approved','rejected')), decided_at REAL);
CREATE TABLE outbox(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), action_id TEXT NOT NULL REFERENCES actions(id), ordinal INTEGER NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('ready','executing','succeeded','failed','uncertain','cancelled')), role TEXT NOT NULL, autonomous INTEGER NOT NULL, discretionary INTEGER NOT NULL DEFAULT 0, is_ask INTEGER NOT NULL DEFAULT 0, available_at REAL NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, receipt TEXT, error TEXT, UNIQUE(action_id,ordinal));
CREATE TABLE delivery_receipts(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), delivery_id TEXT NOT NULL UNIQUE REFERENCES outbox(id), remote_id TEXT, payload TEXT NOT NULL, delivered_at REAL NOT NULL);
CREATE TABLE backend_accounts(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), backend TEXT NOT NULL, account_ref TEXT NOT NULL, label TEXT NOT NULL, billing_mode TEXT NOT NULL CHECK(billing_mode IN ('included_subscription','local','metered','unknown')), pool_id TEXT NOT NULL, models TEXT NOT NULL, capabilities TEXT NOT NULL, fingerprint TEXT NOT NULL, runtime_version TEXT NOT NULL, config_hash TEXT NOT NULL, verified_at REAL NOT NULL, method TEXT NOT NULL, evidence TEXT NOT NULL, status TEXT NOT NULL, quota_status TEXT NOT NULL DEFAULT 'unknown', reset_at REAL, UNIQUE(owner_id,backend,account_ref));
CREATE TABLE usage_observations(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), run_id TEXT NOT NULL REFERENCES runs(id), account_id TEXT NOT NULL REFERENCES backend_accounts(id), input_tokens INTEGER, output_tokens INTEGER, estimated_minor_units INTEGER, billed_minor_units INTEGER, currency TEXT, created_at REAL NOT NULL);
CREATE TABLE blobs(hash TEXT PRIMARY KEY, size INTEGER NOT NULL, mime TEXT NOT NULL, body BLOB, location TEXT, status TEXT NOT NULL CHECK(status IN ('available','removed','missing')), CHECK((body IS NULL)<>(location IS NULL)));
CREATE TABLE artifacts(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), hash TEXT NOT NULL REFERENCES blobs(hash), name TEXT NOT NULL, description TEXT NOT NULL, extracted_text TEXT NOT NULL DEFAULT '', run_id TEXT, validated INTEGER NOT NULL, created_at REAL NOT NULL);
CREATE TABLE artifact_links(owner_id TEXT NOT NULL REFERENCES owners(id), artifact_id TEXT NOT NULL REFERENCES artifacts(id), record_id TEXT NOT NULL, relation TEXT NOT NULL, PRIMARY KEY(artifact_id,record_id,relation));
CREATE TABLE resource_claims(resource TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), job_id TEXT NOT NULL REFERENCES jobs(id), generation INTEGER NOT NULL, lease_until REAL NOT NULL);
CREATE TABLE lifecycle_intervals(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), started_at REAL NOT NULL, ended_at REAL, heartbeat_at REAL NOT NULL, deliberate_pause INTEGER NOT NULL DEFAULT 0);
CREATE TABLE health_events(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), kind TEXT NOT NULL, detail TEXT NOT NULL, created_at REAL NOT NULL);
CREATE TABLE proposals(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), kind TEXT NOT NULL, source_key TEXT NOT NULL, evidence TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('proposed','tested','active','rejected','rolled_back')), evaluation TEXT, created_at REAL NOT NULL, UNIQUE(owner_id,kind,source_key));
CREATE TABLE imports(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), source_hash TEXT NOT NULL, manifest TEXT NOT NULL, created_at REAL NOT NULL, UNIQUE(owner_id,source_hash));
CREATE TABLE import_items(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES owners(id), import_id TEXT NOT NULL REFERENCES imports(id), external_id TEXT NOT NULL, source_hash TEXT NOT NULL, target_id TEXT, status TEXT NOT NULL, detail TEXT NOT NULL, UNIQUE(owner_id,external_id,source_hash));
